/**
 * Messages for one area of the app, in every language. Keys are prefixed by
 * the area so they never collide with another file. English is the source;
 * the other tables are Partial and fall back to English per key. Same rules
 * as messages/en.ts: `{name}` placeholders kept in every language, and no
 * em dash or en dash anywhere (shared/copy-rules.ts).
 *
 * Area: the instrument panels opened only by shortcut. Shift+B Base (with
 * its classifier and analyst tabs, Shift+A), Shift+H Diagnostics, Shift+Q
 * Quant Lab, Shift+S Screen and Shift+T Tracker.
 *
 * What stays out of these tables, on purpose: tickers, provider data, raw
 * enum values and spec field names shown as data (priority bands, routing
 * destinations, composite tags, event_type, cause, edge_status,
 * reaction_state, ...), quant notation (β90, r², vol×, p50), formulas, IDs,
 * file paths, and anything an engine or an LLM wrote (verdicts, caveats,
 * blocked reasons, Gauge checks, failure reasons).
 *
 * A value that is missing or not computable prints `common.na`
 * (lib/i18n/na.ts), never a dash and never a zero; where a message
 * has to name that mark (the Tracker footer), it arrives as `{dash}`.
 *
 * Naming, aligned with the panels area: Base, Tracker, Screen, Gauge and
 * Quant Lab stay as instrument names; Diagnostics, Analyst (the engine),
 * classifier, propagation and risk are translated.
 */
